/**
 * Short histories of the nations' cities, shown in the city screen. Keys are
 * "<civ>-<index>" in the order of the city names in civs.json, so two cities
 * with the same name (Thebes in Egypt and in Greece) keep their own story.
 * The texts follow Wikipedia; `wiki` is the article title to search for.
 */
import { CIV_IDS, CIVS, type CivId } from "../core";
import { language } from "./i18n";

export interface CityPage {
  /** Rough time, as a reader would say it. */
  when: string;
  text: string;
  /** Title of the article on Wikipedia in the page's language. */
  wiki: string;
}

export const CITY_PAGES: Record<string, CityPage> = {
  "romans-0": { when: "od 753 př. n. l.", text: "Podle pověsti Řím založil Romulus na sedmi pahorcích u řeky Tibery. Z malého města vyrostlo centrum říše, která ovládla celé Středomoří, a dnes je to hlavní město Itálie.", wiki: "Řím" },
  "romans-1": { when: "od 6. století př. n. l.", text: "Capua byla jedním z nejbohatších měst Itálie a ležela v úrodné Kampánii. Ve zdejší gladiátorské škole začalo roku 73 př. n. l. Spartakovo povstání.", wiki: "Capua (starověké město)" },
  "romans-2": { when: "od 2. století př. n. l.", text: "Ravenna ležela mezi bažinami u Jaderského moře, a proto se dala dobře bránit. Roku 402 se stala hlavním městem Západořímské říše a dodnes jsou tu slavné mozaiky v kostelech.", wiki: "Ravenna" },
  "romans-3": { when: "od 6. století př. n. l.", text: "Neapol založili řečtí osadníci a pojmenovali ji Neapolis, tedy Nové město. Římané sem jezdili na letní sídla u moře pod sopkou Vesuv.", wiki: "Neapol" },
  "romans-4": { when: "od 7. století př. n. l.", text: "Ostia ležela u ústí Tibery a byla přístavem Říma. Přes ni do města proudilo obilí z Egypta a Afriky, kterým se živily statisíce lidí.", wiki: "Ostia Antica" },
  "romans-5": { when: "zničeny roku 79", text: "Pompeje zasypal popel ze sopky Vesuv při výbuchu roku 79. Pod popelem se zachovaly domy, malby i stopy obyvatel, a tak dnes víme, jak se v římském městě žilo.", wiki: "Pompeje" },
  "romans-6": { when: "od 5. století př. n. l.", text: "Mediolanum založili Keltové a Římané ho dobyli roku 222 př. n. l. Později tu sídlili císaři a roku 313 tu vydali edikt, který povolil křesťanství. Dnes se město jmenuje Milán.", wiki: "Mediolanum" },
  "romans-7": { when: "od 181 př. n. l.", text: "Aquileia vznikla jako římská pevnost na severovýchodě Itálie. Vyrostla v bohaté obchodní město, které roku 452 vyplenil Attila se svými Huny.", wiki: "Aquileia" },
  "romans-8": { when: "od 1. století př. n. l.", text: "Verona ležela na důležitých cestách přes Alpy. Dodnes v ní stojí římská aréna, ve které se dnes hrají opery.", wiki: "Verona" },
  "romans-9": { when: "od 244 př. n. l.", text: "Brundisium bylo přístavem na konci Appiovy cesty. Odtud se lodě plavily do Řecka a na východ. Dnes se město jmenuje Brindisi.", wiki: "Brindisi" },
  "romans-10": { when: "od 8. století př. n. l.", text: "Tarent založili Sparťané a byl to nejmocnější řecký přístav v jižní Itálii. Římané ho dobyli po válce s králem Pyrrhem.", wiki: "Tarent" },
  "romans-11": { when: "od 734 př. n. l.", text: "Syrakusy na Sicílii založili Řekové z Korintu a dlouho patřily k největším městům Středomoří. Žil tu Archimédés, kterého zabil římský voják při dobývání města roku 212 př. n. l.", wiki: "Syrakusy" },
  "romans-12": { when: "od 5. století př. n. l.", text: "Antium bylo přístavní město kmene Volsků, které Řím dobyl roku 338 př. n. l. Narodili se tu císaři Caligula a Nero. Dnes se jmenuje Anzio.", wiki: "Anzio" },
  "romans-13": { when: "etruské město", text: "Arretium bylo jedním z dvanácti etruských měst a proslavilo se červenou keramikou, kterou vyváželo do celé říše. Dnes se jmenuje Arezzo.", wiki: "Arezzo" },
  "romans-14": { when: "od 218 př. n. l.", text: "Placentia vznikla jako římská osada na řece Pád, aby hlídala sever před Kelty. Krátce nato u ní Hannibal porazil Římany. Dnes se jmenuje Piacenza.", wiki: "Piacenza" },
  "romans-15": { when: "od 268 př. n. l.", text: "Ariminum leželo na pobřeží Jaderského moře, kde začínala cesta na sever. U něj teče řeka Rubikon, kterou Caesar překročil roku 49 př. n. l. Dnes se jmenuje Rimini.", wiki: "Rimini" },
  "babylonians-0": { when: "asi od 2300 př. n. l.", text: "Babylón ležel na řece Eufrat a za krále Chammurapiho se stal hlavním městem velké říše. Proslavila ho Ištařina brána a pověst o babylonské věži.", wiki: "Babylón" },
  "babylonians-1": { when: "asi od 3800 př. n. l.", text: "Ur byl jedním z prvních sumerských měst u ústí Eufratu. Archeologové tu našli královské hrobky plné zlata a velký stupňovitý chrám zikkurat.", wiki: "Ur" },
  "babylonians-2": { when: "asi od 4000 př. n. l.", text: "Uruk je jedno z nejstarších měst světa a kolem roku 3000 př. n. l. v něm žilo možná až 40 tisíc lidí. Tady vzniklo jedno z prvních písem a vládl tu bájný král Gilgameš.", wiki: "Uruk" },
  "babylonians-3": { when: "asi od 5000 př. n. l.", text: "Nippur byl svatým městem Sumerů. Stál tu chrám boha Enlila a králové sem chodili pro požehnání své vlády.", wiki: "Nippur" },
  "babylonians-4": { when: "asi od 3100 př. n. l.", text: "Kiš byl podle starých seznamů králů prvním městem, kde po potopě vládli králové. Titul král Kiše pak používali vládci, kteří chtěli ovládat celou Mezopotámii.", wiki: "Kiš (Mezopotámie)" },
  "babylonians-5": { when: "asi od 3000 př. n. l.", text: "Lagaš byl sumerský městský stát, který dlouho válčil se sousední Ummou o vodu a pole. Proslavil ho kníže Gudea, po kterém zbyly desítky kamenných soch.", wiki: "Lagaš" },
  "babylonians-6": { when: "asi od 5400 př. n. l.", text: "Eridu považovali Sumerové za první město na světě, které bohové dali lidem. Leželo u moře na jihu Mezopotámie a uctívalo boha vody Enkiho.", wiki: "Eridu" },
  "babylonians-7": { when: "asi od 3000 př. n. l.", text: "Sippar bylo město boha slunce Šamaše na řece Eufrat. V jeho chrámu se našla knihovna s tisíci hliněných tabulek.", wiki: "Sippar" },
  "babylonians-8": { when: "asi od 3000 př. n. l.", text: "Larsa byla sumerské město boha slunce. Před vzestupem Babylónu ovládala velkou část jižní Mezopotámie, než ji porazil Chammurapi.", wiki: "Larsa" },
  "babylonians-9": { when: "asi od 2000 př. n. l.", text: "Isin se stal mocným po pádu Uru a jeho králové se prohlašovali za vládce Sumeru a Akkadu. Uctívala se tu bohyně léčení Gula.", wiki: "Isin" },
  "babylonians-10": { when: "asi od 2000 př. n. l.", text: "Borsippa ležela kousek od Babylónu a byla městem boha písma a moudrosti Naba. Její zikkurat byl v minulosti považován za babylonskou věž.", wiki: "Borsippa" },
  "babylonians-11": { when: "asi od 2300 př. n. l.", text: "Akkad byl hlavním městem první říše na světě, kterou založil král Sargon. Archeologové ho dodnes nenašli a nikdo neví, kde přesně leží.", wiki: "Akkad (město)" },
  "babylonians-12": { when: "asi od 2900 př. n. l.", text: "Mari leželo na horním Eufratu a bohatlo z obchodu mezi Mezopotámií a Sýrií. V paláci se našel archiv s více než 20 tisíci tabulkami a dopisy králů.", wiki: "Mari (Sýrie)" },
  "babylonians-13": { when: "starověk", text: "Kutha bylo město boha podsvětí Nergala nedaleko Babylónu. Asyrští králové odtud podle Bible přestěhovali lidi do Samaří.", wiki: "Kutha" },
  "babylonians-14": { when: "asi od 3000 př. n. l.", text: "Umma byla soupeřem Lagaše a obě města spolu vedla jednu z prvních zapsaných válek. Její král Lugalzagesi nakonec ovládl skoro celý Sumer.", wiki: "Umma" },
  "babylonians-15": { when: "asi od 3000 př. n. l.", text: "Ešnunna ležela v údolí řeky Dijály a vydala vlastní zákoník ještě před Chammurapim. Archeologové tu našli sošky modlících se lidí s velkýma očima.", wiki: "Ešnunna" },
  "germans-0": { when: "od 13. století", text: "Berlín vyrostl ze dvou kupeckých osad na řece Sprévě. Stal se hlavním městem Pruska a později Německa a po druhé světové válce ho téměř třicet let rozděloval Berlínská zeď.", wiki: "Berlín" },
  "germans-1": { when: "od 9. století", text: "Hamburk leží na řece Labi nedaleko Severního moře a patřil k nejbohatším městům Hanzy. Jeho přístav je dodnes jedním z největších v Evropě.", wiki: "Hamburk" },
  "germans-2": { when: "od 1158", text: "Mnichov založil vévoda Jindřich Lev u mostu přes řeku Isaru, kde se vybíralo clo za sůl. Stal se hlavním městem Bavorska a každý podzim se tu koná Oktoberfest.", wiki: "Mnichov" },
  "germans-3": { when: "od 1. století př. n. l.", text: "Kolín nad Rýnem založili Římané jako Colonia. Ve středověku to bylo největší město Německa a jeho gotickou katedrálu stavěli s přestávkami přes 600 let.", wiki: "Kolín nad Rýnem" },
  "germans-4": { when: "od 8. století", text: "Frankfurt nad Mohanem ležel u brodu, kterým podle pověsti přešli Frankové. Volili se tu římští králové a dnes je to bankovní centrum Evropy.", wiki: "Frankfurt nad Mohanem" },
  "germans-5": { when: "od 1165", text: "Lipsko vyrostlo na křižovatce obchodních cest a proslavily ho veletrhy. Působil tu Johann Sebastian Bach a roku 1989 tu demonstrace pomohly svrhnout komunistický režim.", wiki: "Lipsko" },
  "germans-6": { when: "od 1206", text: "Drážďany na Labi byly sídlem saských kurfiřtů a pro krásné barokní stavby se jim říká Florencie na Labi. Na konci války je zničilo bombardování, ale centrum lidé znovu postavili.", wiki: "Drážďany" },
  "germans-7": { when: "od 1050", text: "Norimberk byl bohaté město řemeslníků a obchodníků a císaři tu často pobývali. Je známý perníkem a po druhé světové válce se tu konaly soudy s nacistickými zločinci.", wiki: "Norimberk" },
  "germans-8": { when: "od 8. století", text: "Brémy na řece Veseře byly sídlem arcibiskupa a členem Hanzy. Dodnes jsou samostatnou spolkovou zemí a znají je děti z pohádky o brémských muzikantech.", wiki: "Brémy" },
  "germans-9": { when: "od 1. století", text: "Cáchy proslavily horké prameny, které využívali už Římané. Karel Veliký tu měl oblíbenou falc a v cášské katedrále se po staletí korunovali němečtí králové.", wiki: "Cáchy" },
  "germans-10": { when: "od 179", text: "Řezno vzniklo jako římská pevnost na Dunaji. Ve středověku tu stál kamenný most, který byl vzorem pro Karlův most v Praze, a zasedal tu říšský sněm.", wiki: "Řezno" },
  "germans-11": { when: "od 15 př. n. l.", text: "Augsburk založili Římané a ve středověku tu sídlila bankéřská rodina Fuggerů, nejbohatší v Evropě. Fuggerové tu postavili Fuggerei, nejstarší sociální bydlení na světě.", wiki: "Augsburk" },
  "germans-12": { when: "od 10. století", text: "Stuttgart vznikl z hřebčína, podle kterého dostal jméno. Stal se hlavním městem Württemberska a dnes tu vyrábějí auta Mercedes a Porsche.", wiki: "Stuttgart" },
  "germans-13": { when: "od 12. století", text: "Hannover byl sídlem hannoverských vévodů, z jejichž rodu pocházeli i britští králové. Dnes se tu každé jaro konají velké průmyslové veletrhy.", wiki: "Hannover" },
  "germans-14": { when: "od 1143", text: "Lübeck byl hlavním městem Hanzy, svazu obchodních měst kolem Baltu a Severního moře. Jeho cihlové gotické domy a brána Holstentor jsou dnes památkou UNESCO.", wiki: "Lübeck" },
  "germans-15": { when: "od 13 př. n. l.", text: "Mohuč založili Římané na soutoku Rýna a Mohanu. Narodil se tu Johannes Gutenberg, který kolem roku 1450 začal tisknout knihy pohyblivými literami.", wiki: "Mohuč" },
  "egyptians-0": { when: "asi od 3200 př. n. l.", text: "Théby byly hlavním městem Egypta v době jeho největší slávy. Stojí tu chrámy v Karnaku a Luxoru a naproti přes Nil leží Údolí králů s hrobkami faraonů.", wiki: "Théby (Egypt)" },
  "egyptians-1": { when: "asi od 3100 př. n. l.", text: "Memfis založil podle tradice první faraon Menes na místě, kde se Nil rozlévá do delty. Byl hlavním městem Staré říše a u něj stojí pyramidy v Sakkáře.", wiki: "Memfis (Egypt)" },
  "egyptians-2": { when: "od 331 př. n. l.", text: "Alexandrii založil Alexandr Veliký na pobřeží Středozemního moře. Stál tu maják, jeden ze sedmi divů světa, a největší knihovna starověku.", wiki: "Alexandrie" },
  "egyptians-3": { when: "od 26. století př. n. l.", text: "Gíza leží na západním břehu Nilu naproti dnešní Káhiře. Stojí tu tři velké pyramidy a Velká sfinga, nejslavnější památky starého Egypta.", wiki: "Gíza" },
  "egyptians-4": { when: "asi od 3000 př. n. l.", text: "Héliopolis bylo město boha slunce Rea. Kněží tu učili o stvoření světa a dodnes tu stojí obelisk, který je přes 4000 let starý.", wiki: "Héliopolis (Egypt)" },
  "egyptians-5": { when: "asi od 3000 př. n. l.", text: "Sais leželo v západní deltě Nilu a uctívalo bohyni Neit. V 7. století př. n. l. odtud pocházeli faraoni, kteří Egypt znovu sjednotili.", wiki: "Sais (Egypt)" },
  "egyptians-6": { when: "asi od 3200 př. n. l.", text: "Abydos bylo posvátné město boha Usira, kam putovali poutníci z celého Egypta. Pohřbili se tu první faraoni a v chrámu Setiho I. je vytesaný seznam králů.", wiki: "Abydos (Egypt)" },
  "egyptians-7": { when: "starověk", text: "Asuán leží na jižní hranici Egypta u prvního nilského kataraktu. Odtud se vozila žula na obelisky a sochy a ve 20. století tu postavili velkou přehradu.", wiki: "Asuán" },
  "egyptians-8": { when: "starověk", text: "Edfu je město boha Hora se sokolí hlavou. Jeho chrám z doby Ptolemaiovců je nejzachovalejším chrámem celého Egypta.", wiki: "Edfu" },
  "egyptians-9": { when: "starověk", text: "Kom Ombo stojí na břehu Nilu a jeho chrám je zasvěcený dvěma bohům najednou, krokodýlímu Sobekovi a sokolímu Horovi. V muzeu u chrámu leží mumie krokodýlů.", wiki: "Kom Ombo" },
  "egyptians-10": { when: "od 1346 př. n. l.", text: "Achetaton postavil faraon Achnaton pro jediného boha slunečního kotouče Atona. Po jeho smrti lidé město opustili a dnes se místu říká Amarna.", wiki: "Amarna" },
  "egyptians-11": { when: "asi od 3500 př. n. l.", text: "Buto bylo jedním z nejstarších měst v deltě Nilu a sídlem bohyně kobry Vadžet. Ochraňovala Dolní Egypt a faraoni nosili její znak na koruně.", wiki: "Buto" },
  "egyptians-12": { when: "od 11. století př. n. l.", text: "Tanis byl hlavním městem faraonů v deltě Nilu. Archeologové tu našli neporušené hrobky králů se stříbrnými rakvemi a zlatými maskami.", wiki: "Tanis" },
  "egyptians-13": { when: "starověk", text: "Bubastis bylo město kočičí bohyně Bastet. Na její svátky sem podle Hérodota připlouvaly statisíce poutníků a kočky se tu pohřbívaly jako mumie.", wiki: "Bubastis" },
  "egyptians-14": { when: "starověk", text: "Hermopolis bylo město boha moudrosti a písma Thovta, kterého lidé zobrazovali s hlavou ibise. Podle místních kněží tu vznikl svět.", wiki: "Hermopolis" },
  "egyptians-15": { when: "starověk", text: "Elefantina je ostrov na Nilu u Asuánu, na kterém se obchodovalo se slonovinou. Stojí tu nilometr, schodiště, kterým kněží měřili výšku záplav.", wiki: "Elefantina" },
  "americans-0": { when: "od 1790", text: "Washington vznikl jako nové hlavní město Spojených států na řece Potomac a jmenuje se po prvním prezidentovi. Stojí tu Bílý dům a Kapitol.", wiki: "Washington, D.C." },
  "americans-1": { when: "od 1624", text: "New York založili Nizozemci jako Nový Amsterdam a Angličané ho roku 1664 přejmenovali. Přes jeho přístav připlouvaly miliony přistěhovalců a dnes je to největší město USA.", wiki: "New York" },
  "americans-2": { when: "od 1630", text: "Boston založili angličtí puritáni. Roku 1773 tu kolonisté vysypali čaj do moře na protest proti daním a brzy nato začala válka za nezávislost.", wiki: "Boston" },
  "americans-3": { when: "od 1682", text: "Filadelfii založil kvaker William Penn a jméno znamená bratrská láska. Roku 1776 tu zástupci kolonií podepsali Deklaraci nezávislosti.", wiki: "Filadelfie" },
  "americans-4": { when: "od 1833", text: "Chicago vyrostlo u jezera Michigan z malé osady na velkoměsto železnic a jatek. Po velkém požáru roku 1871 tu postavili první mrakodrapy.", wiki: "Chicago" },
  "americans-5": { when: "od 1776", text: "San Francisco vzniklo jako španělská misie u velkého zálivu. Zlatá horečka z něj udělala velké město a roku 1906 ho zničilo zemětřesení.", wiki: "San Francisco" },
  "americans-6": { when: "od 1781", text: "Los Angeles založili španělští osadníci jako malou vesnici. Dnes je to druhé největší město USA a sídlí tu filmová studia Hollywoodu.", wiki: "Los Angeles" },
  "americans-7": { when: "od 1837", text: "Atlanta vznikla jako konečná stanice železnice. Za občanské války ji vypálila armáda Severu a později tu žil a kázal Martin Luther King.", wiki: "Atlanta" },
  "americans-8": { when: "od 1851", text: "Seattle leží na severozápadě USA mezi mořem a horami a jmenuje se po indiánském náčelníkovi. Dnes tu sídlí velké technologické firmy.", wiki: "Seattle" },
  "americans-9": { when: "od 1858", text: "Denver založili zlatokopové na úpatí Skalistých hor. Leží asi míli nad mořem, a proto se mu říká Mile High City.", wiki: "Denver" },
  "americans-10": { when: "od 1718", text: "New Orleans založili Francouzi u ústí Mississippi. Roku 1803 ho Spojené státy koupily s celou Louisianou a ve městě se zrodil jazz.", wiki: "New Orleans" },
  "americans-11": { when: "od 1701", text: "Detroit založili Francouzi jako pevnost na řece mezi jezery. Henry Ford tu začal vyrábět auta na pásu a městu se začalo říkat Motor City.", wiki: "Detroit" },
  "americans-12": { when: "od 1836", text: "Houston se jmenuje po Samu Houstonovi, který vybojoval nezávislost Texasu. Bohatne z ropy a sídlí tu řídicí středisko letů NASA.", wiki: "Houston" },
  "americans-13": { when: "od 1729", text: "Baltimore je přístav v zálivu Chesapeake. Při obraně zdejší pevnosti roku 1814 vznikla píseň, která se stala americkou hymnou.", wiki: "Baltimore" },
  "americans-14": { when: "od 1758", text: "Pittsburgh leží na soutoku dvou řek, které tvoří Ohio. Vyrostl z pevnosti v hlavní město americké oceli.", wiki: "Pittsburgh" },
  "americans-15": { when: "od 1896", text: "Miami vzniklo, když na jih Floridy dorazila železnice. Z malé osady se během sta let stalo velkoměsto plné hotelů a přistěhovalců z Kuby a Latinské Ameriky.", wiki: "Miami" },
  "greeks-0": { when: "od 2. tisíciletí př. n. l.", text: "Atény byly kolébkou demokracie a filozofie. Na skále Akropoli nad městem stojí chrám Parthenón zasvěcený bohyni Athéně.", wiki: "Atény" },
  "greeks-1": { when: "od 10. století př. n. l.", text: "Sparta byla vojenský stát, ve kterém chlapci od sedmi let cvičili na vojáky. Tři sta Sparťanů s králem Leónidem bojovalo roku 480 př. n. l. u Thermopyl proti Peršanům.", wiki: "Sparta" },
  "greeks-2": { when: "od 8. století př. n. l.", text: "Korint ležel na šíji mezi dvěma moři a bohatl z obchodu na obou stranách. Lodě se tu přetahovaly po kamenné dráze z jednoho moře do druhého.", wiki: "Korint" },
  "greeks-3": { when: "od 2. tisíciletí př. n. l.", text: "Théby v Boiótii byly rodištěm hrdiny Hérakla a krále Oidipa z řeckých bájí. Roku 371 př. n. l. porazily Spartu a krátce byly nejsilnějším městem Řecka.", wiki: "Théby (Řecko)" },
  "greeks-4": { when: "od 2. tisíciletí př. n. l.", text: "Argos je jedno z nejstarších nepřetržitě obývaných měst Evropy. Dlouho soupeřilo se Spartou o vládu nad Peloponésem.", wiki: "Argos" },
  "greeks-5": { when: "od 8. století př. n. l.", text: "Delfy ležely na svahu hory Parnas a Řekové je považovali za střed světa. V Apollónově chrámu tu věštkyně Pýthie odpovídala na otázky králů i obyčejných lidí.", wiki: "Delfy" },
  "greeks-6": { when: "od 776 př. n. l.", text: "Olympie byla svaté místo boha Dia. Každé čtyři roky se tu konaly olympijské hry a během nich musely války mezi řeckými městy ustat.", wiki: "Olympie" },
  "greeks-7": { when: "od 10. století př. n. l.", text: "Milétos na pobřeží Malé Asie založil desítky osad kolem Středozemního a Černého moře. Žili tu první řečtí filozofové, mezi nimi Thalés.", wiki: "Milétos" },
  "greeks-8": { when: "od 10. století př. n. l.", text: "Efesos byl velký přístav v Malé Asii. Stál tu Artemidin chrám, jeden ze sedmi divů světa, a dodnes tu stojí průčelí Celsovy knihovny.", wiki: "Efesos" },
  "greeks-9": { when: "od 408 př. n. l.", text: "Rhodos je ostrovní město na cestě mezi Řeckem a Egyptem. U jeho přístavu stál obří bronzový Kolos, jeden ze sedmi divů světa.", wiki: "Rhodos (město)" },
  "greeks-10": { when: "od 2. tisíciletí př. n. l.", text: "Mykény byly sídlem bájného krále Agamemnóna, který vedl Řeky do trojské války. Do města se vcházelo Lví branou a archeolog Schliemann tu našel zlatou masku.", wiki: "Mykény" },
  "greeks-11": { when: "starověk", text: "Sikyón leželo nedaleko Korintu a proslavilo se malíři a sochaři. Podle jedné řecké pověsti tu vzniklo malířství.", wiki: "Sikyón" },
  "greeks-12": { when: "od 8. století př. n. l.", text: "Megara ležela mezi Aténami a Korintem a zakládala osady daleko od domova. Jedna z nich, Byzantion, se později stala Konstantinopolí.", wiki: "Megara" },
  "greeks-13": { when: "starověk", text: "Eretrie na ostrově Euboia patřila k prvním řeckým městům, která zakládala osady v Itálii. Roku 490 př. n. l. ji vypálili Peršané těsně před bitvou u Marathónu.", wiki: "Eretrie" },
  "greeks-14": { when: "starověk", text: "Chalkis leží na ostrově Euboia u úžiny, kde se proud mění několikrát za den. Zemřel tu filozof Aristotelés.", wiki: "Chalkis" },
  "greeks-15": { when: "od 5. století př. n. l.", text: "Pella byla hlavním městem Makedonie. Narodil se tu Alexandr Veliký a jeho otec Filip II. povolal do Makedonie Aristotela, aby syna učil.", wiki: "Pella" },
  "indians-0": { when: "od 6. století př. n. l.", text: "Dillí leží na řece Jamuně a bylo hlavním městem mnoha říší, naposledy Mughalské. Mughalové tu postavili Červenou pevnost a dnes je Nové Dillí hlavním městem Indie.", wiki: "Dillí" },
  "indians-1": { when: "od 16. století", text: "Bombaj vznikla ze sedmi ostrovů, které Portugalci darovali anglickému králi jako věno. Angličané ostrovy spojili a z města se stal největší přístav Indie. Dnes se jmenuje Mumbaj a točí se tu filmy Bollywoodu.", wiki: "Bombaj" },
  "indians-2": { when: "od 1690", text: "Kalkatu založila Britská Východoindická společnost na řece Huglí. Do roku 1911 byla hlavním městem Britské Indie a dnes se jmenuje Kolkata.", wiki: "Kalkata" },
  "indians-3": { when: "od 1639", text: "Madrás vyrostl kolem anglické pevnosti svatého Jiří na východním pobřeží Indie. Byl první velkou anglickou osadou v Indii a dnes se jmenuje Čennaí.", wiki: "Čennaí" },
  "indians-4": { when: "od 2. tisíciletí př. n. l.", text: "Váránasí na řece Ganze je jedno z nejstarších obývaných měst světa a nejposvátnější město hinduistů. Poutníci se tu koupou v řece a na jejím břehu se pálí zemřelí.", wiki: "Váránasí" },
  "indians-5": { when: "od 16. století", text: "Ágra byla hlavním městem Mughalské říše. Císař Šáhdžahán tu dal postavit Tádž Mahal jako hrobku pro svou zemřelou manželku.", wiki: "Ágra" },
  "indians-6": { when: "od 1727", text: "Džajpur založil maharádža Džaj Singh II. podle přesného plánu s rovnými ulicemi. Domy ve starém městě jsou natřené narůžovělou barvou, a tak se mu říká Růžové město.", wiki: "Džajpur" },
  "indians-7": { when: "od 5. století př. n. l.", text: "Pátna se dřív jmenovala Pátaliputra a byla hlavním městem Maurjovské říše krále Ašóky. Patřila k největším městům starověkého světa.", wiki: "Pátna" },
  "indians-8": { when: "od 18. století", text: "Lakhnaú bylo sídlem navábů z Avadhu a proslavilo se poezií a kuchyní. Roku 1857 tu Britové měsíce bránili svou rezidenci při velkém povstání.", wiki: "Lakhnaú" },
  "indians-9": { when: "od 1591", text: "Hajdarábád založil sultán z Golkondy a uprostřed města stojí brána Čár Minár se čtyřmi věžemi. Z nedalekých dolů pocházely slavné diamanty jako Kohinúr.", wiki: "Hajdarábád" },
  "indians-10": { when: "od 1537", text: "Bengalúru založil místní vládce Kempegauda jako pevnost na náhorní plošině. Dnes je to indické centrum počítačových firem.", wiki: "Bengalúru" },
  "indians-11": { when: "od 1577", text: "Amritsar je posvátné město Sikhů. Stojí tu Zlatý chrám uprostřed jezera, kde každý den dostanou jídlo zadarmo desetitisíce lidí.", wiki: "Amritsar" },
  "indians-12": { when: "od 1559", text: "Udajpur založil mahárána z Méváru u umělého jezera. Kvůli jezerům a palácům mu lidé říkají Benátky východu.", wiki: "Udajpur" },
  "indians-13": { when: "od 8. století", text: "Puné bylo centrem Maráthské říše a sídlem jejích ministrů péšvů. Dnes je to velké univerzitní město.", wiki: "Puné" },
  "indians-14": { when: "od 18. století", text: "Indaur vyrostl jako obchodní město ve středu Indie. V 18. století tu vládla moudrá královna Ahilja Baí Holkar.", wiki: "Indaur" },
  "indians-15": { when: "od 14. století", text: "Májsúr byl hlavním městem království Majsúr. Každý podzim tu slaví svátek Dasara a palác se rozsvítí desítkami tisíc žárovek.", wiki: "Májsúr" },
  "russians-0": { when: "od 1147", text: "Moskva se poprvé připomíná roku 1147 jako malé hradiště na řece Moskvě. Z moskevského knížectví vyrostla ruská říše a uprostřed města stojí Kreml a Rudé náměstí.", wiki: "Moskva" },
  "russians-1": { when: "od 1703", text: "Petrohrad založil car Petr Veliký v bažinách u Baltského moře jako okno do Evropy. Dvě stě let byl hlavním městem Ruska a za války vydržel 872 dní německého obléhání.", wiki: "Petrohrad" },
  "russians-2": { when: "od 859", text: "Novgorod je jedno z nejstarších ruských měst. Byl bohatou kupeckou republikou, kde o důležitých věcech rozhodovalo shromáždění obyvatel.", wiki: "Velikij Novgorod" },
  "russians-3": { when: "od 990", text: "Vladimir byl ve 12. století hlavním městem severovýchodní Rusi. Stojí tu bílé kamenné chrámy a Zlatá brána, které přečkaly vpád Mongolů.", wiki: "Vladimir (Rusko)" },
  "russians-4": { when: "od 1005", text: "Kazaň byla hlavním městem tatarského chanátu na řece Volze. Ivan Hrozný ji dobyl roku 1552 a dnes je centrem Tatarstánu.", wiki: "Kazaň" },
  "russians-5": { when: "od 12. století", text: "Tver ležela na horní Volze a dlouho soupeřila s Moskvou o vedení ruských knížectví. Odtud se vydal kupec Afanasij Nikitin na cestu do Indie.", wiki: "Tver" },
  "russians-6": { when: "od 1010", text: "Jaroslavl založil kníže Jaroslav Moudrý na soutoku Volhy a Kotorosli. Patří do Zlatého kruhu starých měst kolem Moskvy.", wiki: "Jaroslavl" },
  "russians-7": { when: "od 863", text: "Smolensk leží na Dněpru na cestě mezi Moskvou a Evropou. Proto se o něj mnohokrát bojovalo, mimo jiné s Napoleonem roku 1812.", wiki: "Smolensk" },
  "russians-8": { when: "od 903", text: "Pskov byl pevnost na západní hranici Rusi. Jeho kamenné hradby odolaly mnoha obléháním, mimo jiné polského krále Štěpána Báthoryho.", wiki: "Pskov" },
  "russians-9": { when: "od 1221", text: "Nižnij Novgorod stojí na soutoku Volhy a Oky. Roku 1612 tu kupec Minin a kníže Požarskij sebrali vojsko, které vyhnalo Poláky z Moskvy.", wiki: "Nižnij Novgorod" },
  "russians-10": { when: "od 1586", text: "Samara vznikla jako pevnost na Volze, která chránila obchodní cestu. Za druhé světové války sem vláda přestěhovala úřady a velvyslanectví z Moskvy.", wiki: "Samara" },
  "russians-11": { when: "od 1584", text: "Archangelsk byl dlouho jediným ruským námořním přístavem. Leží u Bílého moře, které je část roku zamrzlé.", wiki: "Archangelsk" },
  "russians-12": { when: "od 862", text: "Rostov Velikij je jedno z nejstarších ruských měst u jezera Nero. Proslavil ho kreml s kostely a zvony, které hrají melodie.", wiki: "Rostov Velikij" },
  "russians-13": { when: "od 1146", text: "Tula proslavily zbrojovky a samovary. Pečou tu také perník a nedaleko ležel statek Lva Tolstého.", wiki: "Tula (Rusko)" },
  "russians-14": { when: "od 1586", text: "Voroněž vznikla jako pevnost proti nájezdníkům ze stepi. Petr Veliký tu dal postavit první loďstvo ruského námořnictva.", wiki: "Voroněž" },
  "russians-15": { when: "od 1723", text: "Jekatěrinburg založili na Uralu jako železárny a pevnost. Roku 1918 tu bolševici zastřelili posledního cara Mikuláše II. s rodinou.", wiki: "Jekatěrinburg" },
  "zulus-0": { when: "od 1820", text: "KwaBulawayo byl královský kraal, který postavil Šaka. Jméno znamená místo, kde se zabíjí, a odtud Šaka řídil vznik zulské říše.", wiki: "KwaBulawayo" },
  "zulus-1": { when: "od 1826", text: "Dukuza byla poslední Šakovou královskou osadou blízko pobřeží Indického oceánu. Roku 1828 tu Šaku zavraždili jeho nevlastní bratři. Dnes tu stojí město KwaDukuza.", wiki: "KwaDukuza" },
  "zulus-2": { when: "od 1873", text: "Ulundi bylo královským sídlem krále Cetshwaya. Roku 1879 tu britská armáda v poslední bitvě zulské války porazila Zuly a sídlo vypálila.", wiki: "Ulundi" },
  "zulus-3": { when: "od 1860", text: "Eshowe leží v kopcích nad pobřežím a je jedním z nejstarších měst Zululandu. Za zulské války tu Zulové několik týdnů obléhali britskou posádku.", wiki: "Eshowe" },
  "zulus-4": { when: "od 19. století", text: "Nongoma je sídlem dnešního zulského krále. Leží v kopcích severního Zululandu, kde žije mnoho tradičních zulských rodin.", wiki: "Nongoma" },
  "zulus-5": { when: "bitva 1879", text: "Isandlwana je hora se skalním vrcholem, pod kterou roku 1879 zulské vojsko porazilo britskou armádu. Byla to jedna z nejhorších porážek Britů v koloniálních válkách.", wiki: "Isandlwana" },
  "zulus-6": { when: "19. století", text: "Mahlabatini leží na rovině u řeky Bílé Umfolozi, kde stály královské osady zulských králů. Okolí se říká údolí králů, protože jsou tu pohřbeni předkové Šaky.", wiki: "Mahlabatini" },
  "zulus-7": { when: "19. století", text: "Nkandla leží v hustých lesích a kopcích, kam se Zulové uchylovali v časech války. Roku 1906 se tu skrývali povstalci náčelníka Bambathy.", wiki: "Nkandla" },
  "zulus-8": { when: "19. století", text: "Babanango je malé městečko na náhorní plošině uprostřed Zululandu. Okolní pastviny dobře znali zulští pastevci dobytka.", wiki: "Babanango" },
  "zulus-9": { when: "19. století", text: "Ngome je les na horách severního Zululandu s obřími stromy a vzácnými orchidejemi. Zulští králové tu měli loviště a útočiště.", wiki: "Ngome Forest" },
  "zulus-10": { when: "bitva 1879", text: "Hlobane je hora s plochým vrcholem. Roku 1879 tu Zulové porazili britskou jízdu, ale den nato prohráli u nedalekého Kambula.", wiki: "Hlobane" },
  "zulus-11": { when: "od 19. století", text: "Empangeni leží blízko pobřeží v krajině cukrové třtiny. Vyrostlo z misijní stanice v rušné město.", wiki: "Empangeni" },
  "zulus-12": { when: "20. století", text: "Mtubatuba se jmenuje po náčelníkovi, který tu žil. Leží blízko národních parků, kde žijí nosorožci a sloni.", wiki: "Mtubatuba" },
  "zulus-13": { when: "19. století", text: "Pongola leží u řeky Pongoly na severní hranici Zululandu. Řeka dlouho oddělovala zulské území od Svazijska.", wiki: "Pongola" },
  "zulus-14": { when: "19. století", text: "Tugela je největší řeka KwaZulu-Natalu a dlouho tvořila hranici zulského království. Na jejím horním toku padá vodopád, jeden z nejvyšších na světě.", wiki: "Tugela" },
  "zulus-15": { when: "19. století", text: "Umfolozi jsou dvě řeky, Bílá a Černá, mezi kterými leželo srdce zulského království. Dnes tu je rezervace, která zachránila nosorožce před vyhubením.", wiki: "Umfolozi" },
  "french-0": { when: "od 3. století př. n. l.", text: "Paříž vyrostla z keltské osady na ostrově uprostřed Seiny. Stala se hlavním městem Francie a stojí v ní katedrála Notre-Dame a Eiffelova věž.", wiki: "Paříž" },
  "french-1": { when: "starověk", text: "Orléans leží na řece Loiře. Roku 1429 ho Johanka z Arku osvobodila od Angličanů, a proto se jí říká Panna orleánská.", wiki: "Orléans" },
  "french-2": { when: "od 43 př. n. l.", text: "Lyon založili Římané na soutoku Rhôny a Saôny jako hlavní město Galie. Později proslul výrobou hedvábí a bratři Lumièrové tu natočili první filmy.", wiki: "Lyon" },
  "french-3": { when: "od 600 př. n. l.", text: "Marseille založili řečtí námořníci a je to nejstarší město Francie. Jeho přístav je dodnes největší ve Francii a po městě se jmenuje francouzská hymna.", wiki: "Marseille" },
  "french-4": { when: "od 3. století př. n. l.", text: "Bordeaux leží na řece Garonně blízko Atlantiku. Proslavilo ho víno, které se odtud po staletí vyváželo do celého světa.", wiki: "Bordeaux" },
  "french-5": { when: "starověk", text: "V Remeši se v gotické katedrále korunovali francouzští králové. Johanka z Arku sem roku 1429 dovedla krále Karla VII. ke korunovaci.", wiki: "Remeš" },
  "french-6": { when: "starověk", text: "Rouen leží na Seině v Normandii. Roku 1431 tu Angličané upálili Johanku z Arku.", wiki: "Rouen" },
  "french-7": { when: "starověk", text: "Toulouse bylo hlavním městem Vizigótů a později hrabat z Toulouse. Kvůli cihlovým domům se mu říká Růžové město a dnes se tu stavějí letadla Airbus.", wiki: "Toulouse" },
  "french-8": { when: "od 12 př. n. l.", text: "Štrasburk leží na Rýně na hranici Francie a Německa a patřil střídavě oběma zemím. Dnes tu sídlí Evropský parlament.", wiki: "Štrasburk" },
  "french-9": { when: "starověk", text: "Nantes leží u ústí Loiry. Roku 1598 tu král Jindřich IV. podepsal Nantský edikt, který povolil protestantům jejich víru.", wiki: "Nantes" },
  "french-10": { when: "starověk", text: "V Avignonu na Rhôně sídlili ve 14. století papežové. Postavili tu obrovský papežský palác a ve městě je slavný most, o kterém se zpívá písnička.", wiki: "Avignon" },
  "french-11": { when: "starověk", text: "Dijon byl hlavním městem burgundských vévodů, kteří vládli bohaté zemi. Proslavila ho hořčice.", wiki: "Dijon" },
  "french-12": { when: "od 11. století", text: "Lille na severu Francie vyrostlo z obchodu se suknem. Narodil se tu generál a prezident Charles de Gaulle.", wiki: "Lille" },
  "french-13": { when: "od 4. století př. n. l.", text: "Nice založili Řekové na pobřeží Středozemního moře. Dlouho patřila Savojsku a k Francii se připojila až roku 1860.", wiki: "Nice" },
  "french-14": { when: "starověk", text: "Grenoble leží v údolí obklopeném Alpami. Roku 1968 tu byly zimní olympijské hry.", wiki: "Grenoble" },
  "french-15": { when: "starověk", text: "Tours leží na Loiře. Roku 732 nedaleko odtud Karel Martel zastavil arabské vojsko, které táhlo z Hispánie.", wiki: "Tours" },
  "aztecs-0": { when: "od 1325", text: "Tenochtitlán postavili Aztékové na ostrově v jezeře Texcoco, kde podle pověsti uviděli orla na kaktusu. S pevninou ho spojovaly hráze a stálo v něm možná přes 200 tisíc lidí. Na jeho troskách dnes stojí Ciudad de México.", wiki: "Tenochtitlán" },
  "aztecs-1": { when: "od 1337", text: "Tlatelolco bylo sesterské město Tenochtitlánu na sousedním ostrově. Konal se tu největší trh Ameriky, na který denně chodily desetitisíce lidí.", wiki: "Tlatelolco (altepetl)" },
  "aztecs-2": { when: "od 12. století", text: "Texcoco leželo na východním břehu jezera a patřilo do trojspolku s Tenochtitlánem. Za krále básníka Nezahualcoyotla bylo centrem vzdělanosti a umění.", wiki: "Texcoco (altepetl)" },
  "aztecs-3": { when: "od 13. století", text: "Tlacopan na západním břehu jezera bylo třetím a nejmenším členem aztéckého trojspolku. Vedla k němu hráz, po které Španělé v noci prchali z Tenochtitlánu.", wiki: "Tlacopan" },
  "aztecs-4": { when: "asi od 100 př. n. l.", text: "Teotihuacán bylo obří město se Sluneční a Měsíční pyramidou, opuštěné dávno před Aztéky. Aztékové věřili, že tu bohové stvořili slunce, a dali mu jméno místo, kde se rodí bohové.", wiki: "Teotihuacán" },
  "aztecs-5": { when: "od 3. století př. n. l.", text: "Cholula má největší pyramidu na světě podle objemu, dnes zarostlou trávou jako kopec. Na jejím vrcholu postavili Španělé kostel.", wiki: "Cholula (Mezoamerika)" },
  "aztecs-6": { when: "od 10. století", text: "Tula byla hlavním městem Toltéků, které Aztékové obdivovali jako mistry všech řemesel. Na vrcholu pyramidy tu stojí obří kamenní válečníci.", wiki: "Tula (Mezoamerika)" },
  "aztecs-7": { when: "starověk", text: "Xochimilco leží na jihu jezera a jeho obyvatelé pěstovali plodiny na umělých plovoucích zahradách. Mezi zahradami dodnes vedou kanály, po kterých se plují barevné lodě.", wiki: "Xochimilco" },
  "aztecs-8": { when: "starověk", text: "Coyoacán leželo na jižním břehu jezera. Po dobytí Tenochtitlánu tu Hernán Cortés nějakou dobu sídlil a o staletí později tu žila malířka Frida Kahlo.", wiki: "Coyoacán" },
  "aztecs-9": { when: "od 14. století", text: "Tlaxcala byla horská republika, kterou Aztékové nikdy nedobyli. Její bojovníci se proto spojili se Španěly a pomohli jim Tenochtitlán dobýt.", wiki: "Tlaxcala (altepetl)" },
  "aztecs-10": { when: "od 15. století", text: "Malinalco je chrám tesaný přímo do skály na svahu hory. Zasvěcovali se v něm aztéčtí bojovníci řádů orla a jaguára.", wiki: "Malinalco" },
  "aztecs-11": { when: "starověk", text: "Chalco leželo u stejnojmenného jezera na jihovýchodě údolí. Aztékové ho po dlouhé válce dobyli v 15. století a jeho úrodná pole živila hlavní město.", wiki: "Chalco (altepetl)" },
  "aztecs-12": { when: "od 12. století", text: "Azcapotzalco bylo hlavním městem Tepaneků, kterým Aztékové dlouho platili daně. Roku 1428 ho Aztékové s Texcocem porazili a začal vzestup aztécké říše.", wiki: "Azcapotzalco" },
  "aztecs-13": { when: "starověk", text: "Cuauhnáhuac leželo v teplém údolí jižně od hor a Aztékové odtud dostávali bavlnu. Cortés si tu postavil palác a dnes se město jmenuje Cuernavaca.", wiki: "Cuernavaca" },
  "aztecs-14": { when: "starověk", text: "Huexotzinco leželo na svazích sopky Iztaccíhuatl a stejně jako Tlaxcala vzdorovalo Aztékům. S Aztéky vedlo takzvané květinové války, ve kterých se chytali zajatci pro oběti.", wiki: "Huejotzingo" },
  "aztecs-15": { when: "starověk", text: "Tepeyacac byl kopec na severním břehu jezera, kam vedla hráz z Tenochtitlánu. Podle tradice se tu roku 1531 zjevila Panna Maria Guadalupská a dnes tu stojí poutní bazilika.", wiki: "Tepeyac" },
  "chinese-0": { when: "od 1045 př. n. l.", text: "Peking byl hlavním městem většiny posledních čínských dynastií. Uprostřed leží Zakázané město, palác císařů s téměř 1000 budovami.", wiki: "Peking" },
  "chinese-1": { when: "od 11. století př. n. l.", text: "Si-an se dřív jmenovalo Čchang-an a bylo hlavním městem více než deseti dynastií. Začínala tu Hedvábná stezka a nedaleko leží terakotová armáda prvního císaře.", wiki: "Si-an" },
  "chinese-2": { when: "od 10. století", text: "Šanghaj byla rybářská a obchodní osada u ústí Jang-c'-ťiang. V 19. století se otevřela cizincům a dnes je to největší město Číny.", wiki: "Šanghaj" },
  "chinese-3": { when: "od 5. století př. n. l.", text: "Nanking leží na řece Jang-c'-ťiang a jméno znamená jižní hlavní město. Několikrát byl hlavním městem Číny a jeho městské hradby patří k nejdelším na světě.", wiki: "Nanking" },
  "chinese-4": { when: "od 214 př. n. l.", text: "Kanton leží na Perlové řece na jihu Číny a odedávna obchodoval s cizinci po moři. Dlouho to byl jediný čínský přístav, kam směli evropští obchodníci. Dnes se jmenuje Kuang-čou.", wiki: "Kuang-čou" },
  "chinese-5": { when: "od 2. tisíciletí př. n. l.", text: "Luo-jang leží na Žluté řece a bylo hlavním městem mnoha starých dynastií. Do skal nad řekou tu mniši vytesali desetitisíce soch Buddhy.", wiki: "Luo-jang" },
  "chinese-6": { when: "od 2. století př. n. l.", text: "Chang-čou leží u Západního jezera, které opěvovali básníci. Ve 12. a 13. století bylo hlavním městem Číny a Marco Polo ho označil za nejkrásnější město světa.", wiki: "Chang-čou" },
  "chinese-7": { when: "od 4. století př. n. l.", text: "Čcheng-tu leží v úrodné pánvi S'-čchuanu. Nedaleko stojí přes 2000 let starý zavlažovací systém, který dodnes funguje, a v okolí žijí pandy.", wiki: "Čcheng-tu" },
  "chinese-8": { when: "od 4. století př. n. l.", text: "Kchaj-feng na Žluté řece bylo za dynastie Sung hlavním městem a jedním z největších měst světa. Řeka ho mnohokrát zaplavila.", wiki: "Kchaj-feng" },
  "chinese-9": { when: "starověk", text: "Wu-chan vzniklo ze tří měst na soutoku Jang-c'-ťiang a řeky Chan. Roku 1911 tu vypuklo povstání, které svrhlo posledního čínského císaře.", wiki: "Wu-chan" },
  "chinese-10": { when: "od 514 př. n. l.", text: "Su-čou protínají kanály, a tak se mu říká čínské Benátky. Proslavily ho klasické zahrady a výroba hedvábí.", wiki: "Su-čou" },
  "chinese-11": { when: "od 1404", text: "Tchien-ťin vznikl jako pevnost a přístav pro Peking u ústí Velkého kanálu. Dnes je to jedno z největších měst Číny.", wiki: "Tchien-ťin" },
  "chinese-12": { when: "od 4. století př. n. l.", text: "Čchung-čching leží v horách na soutoku Jang-c'-ťiang a Ťia-ling. Za druhé světové války tu sídlila čínská vláda a Japonci město mnohokrát bombardovali.", wiki: "Čchung-čching" },
  "chinese-13": { when: "od 214 př. n. l.", text: "Kuej-lin obklopují strmé vápencové kopce a řeka Li. Krajinu kolem malují čínští malíři odedávna.", wiki: "Kuej-lin" },
  "chinese-14": { when: "od 3. století př. n. l.", text: "Ta-tchung leží na severu u Velké zdi a bylo hlavním městem dynastie Severní Wej. Nedaleko jsou jeskyně Jün-kang s tisíci tesaných soch Buddhy.", wiki: "Ta-tchung" },
  "chinese-15": { when: "starověk", text: "Ťi-nan se říká město pramenů, protože v něm vyvěrají desítky pramenů. Leží blízko posvátné hory Tchaj-šan.", wiki: "Ťi-nan" },
  "english-0": { when: "od 47", text: "Londýn založili Římané jako Londinium u brodu přes Temži. Stal se hlavním městem Anglie a později centrem největší říše v dějinách.", wiki: "Londýn" },
  "english-1": { when: "od 71", text: "York založili Římané jako pevnost Eboracum, později tu vládli Vikingové jako v Jórviku. Jeho gotická katedrála patří k největším v severní Evropě.", wiki: "York" },
  "english-2": { when: "od 6. století", text: "Nottingham má hrad na skále, pod kterou vedou stovky jeskyní. Podle legendy tu sídlil šerif, se kterým bojoval Robin Hood ze Sherwoodského lesa.", wiki: "Nottingham" },
  "english-3": { when: "od 1. století", text: "V Canterbury začal roku 597 svatý Augustin šířit křesťanství mezi Angly. Roku 1170 tu v katedrále zavraždili arcibiskupa Tomáše Becketa a město se stalo poutním místem.", wiki: "Canterbury" },
  "english-4": { when: "od 9. století", text: "Oxford vznikl u brodu, kterým se hnal dobytek přes Temži. Na konci 11. století tu začali učit a vznikla nejstarší univerzita anglicky mluvícího světa.", wiki: "Oxford" },
  "english-5": { when: "od 1. století", text: "Cambridge leží na řece Cam. Roku 1209 sem utekli učenci z Oxfordu a založili univerzitu, na které studovali Newton i Darwin.", wiki: "Cambridge" },
  "english-6": { when: "od 11. století", text: "Bristol byl velký přístav na západě Anglie. Odtud roku 1497 vyplul John Cabot a doplul do Severní Ameriky.", wiki: "Bristol" },
  "english-7": { when: "od 1207", text: "Liverpool byl přístav, odkud vyplouvaly lodě do Ameriky. V 60. letech 20. století tu začali hrát Beatles.", wiki: "Liverpool" },
  "english-8": { when: "od 79", text: "Manchester vznikl z římské pevnosti a v 18. století se stal prvním průmyslovým městem světa. Tkalcovny bavlny tu poháněly parní stroje.", wiki: "Manchester" },
  "english-9": { when: "od 7. století", text: "Birmingham byla malá tržní vesnice, která v průmyslové revoluci vyrostla v město tisíce řemesel. Pracovali tu vynálezci James Watt a Matthew Boulton.", wiki: "Birmingham" },
  "english-10": { when: "starověk", text: "Winchester byl hlavním městem anglosaského království Wessex za krále Alfréda Velikého. V jeho katedrále je pohřbena spisovatelka Jane Austenová.", wiki: "Winchester" },
  "english-11": { when: "starověk", text: "Dover leží na nejužším místě kanálu La Manche, odkud je za jasného dne vidět Francie. Nad přístavem se tyčí bílé křídové útesy a hrad.", wiki: "Dover" },
  "english-12": { when: "od 13. století", text: "Plymouth je přístav na jihozápadě Anglie. Odtud vyplul Francis Drake proti španělské Armadě a roku 1620 loď Mayflower s poutníky do Ameriky.", wiki: "Plymouth" },
  "english-13": { when: "od 5. století", text: "Leeds vyrostlo z obchodu s vlnou a v průmyslové revoluci se stalo velkým městem soukenictví. Dnes je to velké obchodní a univerzitní město.", wiki: "Leeds" },
  "english-14": { when: "od 7. století", text: "Norwich byl ve středověku po Londýně jedním z největších a nejbohatších měst Anglie. Bohatl z vlny a má katedrálu s vysokou věží.", wiki: "Norwich" },
  "english-15": { when: "od 60", text: "Bath postavili Římané u horkých pramenů a pojmenovali Aquae Sulis. Římské lázně se tu zachovaly dodnes a v 18. století sem jezdila celá anglická smetánka.", wiki: "Bath" },
  "mongols-0": { when: "od 1220", text: "Karakorum bylo hlavním městem Mongolské říše za Čingischánových nástupců. Na dvůr velkého chána sem přijížděli vyslanci z Evropy i Asie. Na jeho místě dnes stojí klášter Erdene Zuu.", wiki: "Karakorum" },
  "mongols-1": { when: "13. století", text: "Avraga byla podle archeologů první sídlo Čingischána u řeky Cherlen. Na místě se našly zbytky jeho tábora a dílen.", wiki: "Avraga" },
  "mongols-2": { when: "od 1267", text: "Chanbalyk nechal postavit chán Kublaj jako hlavní město čínské dynastie Jüan. Marco Polo popsal jeho nádheru a na jeho místě dnes stojí Peking.", wiki: "Chanbalyk" },
  "mongols-3": { when: "od 1256", text: "Šang-tu bylo letní sídlo chána Kublaje. Evropané ho znají z básně jako Xanadu, místo pohádkového přepychu.", wiki: "Šang-tu" },
  "mongols-4": { when: "od 13. století", text: "Sarai na dolní Volze bylo hlavním městem Zlaté hordy, která vládla Rusi. Bylo to jedno z největších měst středověku a obchodovalo se tu s Evropou i Čínou.", wiki: "Saraj (Zlatá horda)" },
  "mongols-5": { when: "starověk", text: "Tabríz byl hlavním městem mongolských íl-chánů v Persii. Jeho velký krytý bazar patří k nejstarším na světě.", wiki: "Tabríz" },
  "mongols-6": { when: "od 1302", text: "Sultáníju postavili íl-cháni jako nové hlavní město. Zbyla z ní obrovská hrobka chána Öldžejtüa s jednou z největších kupolí na světě.", wiki: "Sultáníja" },
  "mongols-7": { when: "13. století", text: "Almalyk bylo hlavním městem Čagatajského chanátu ve střední Asii na Hedvábné stezce. Dnes po něm zbyly jen trosky.", wiki: "Almalyk (středověké město)" },
  "mongols-8": { when: "od 1639", text: "Ulánbátar vznikl jako putovní klášter, který se stěhoval z místa na místo. Dnes je to hlavní město Mongolska a žije v něm skoro polovina obyvatel země.", wiki: "Ulánbátar" },
  "mongols-9": { when: "od 1974", text: "Erdenet vznikl u velkého dolu na měď. Je to druhé největší město Mongolska.", wiki: "Erdenet" },
  "mongols-10": { when: "od 1961", text: "Darchan postavili jako průmyslové město na severu Mongolska. Jméno znamená kovář.", wiki: "Darchan" },
  "mongols-11": { when: "od 1762", text: "Chovd vznikl jako pevnost čínské dynastie Čching na západě Mongolska. Leží v kraji, kde žije mnoho různých kmenů.", wiki: "Chovd" },
  "mongols-12": { when: "20. století", text: "Mörön leží na severu Mongolska blízko jezera Chövsgöl. V okolí stojí staré kamenné stély s vytesanými jeleny.", wiki: "Mörön" },
  "mongols-13": { when: "20. století", text: "Čojbalsan leží na východě Mongolska u řeky Cherlen. Jmenuje se po Chorlogijnu Čojbalsanovi, který zemi vládl ve 30. a 40. letech 20. století.", wiki: "Čojbalsan" },
  "mongols-14": { when: "20. století", text: "Bajanchongor leží mezi pohořím Changaj a pouští Gobi. Kolem se pasou stáda ovcí a velbloudů.", wiki: "Bajanchongor" },
  "mongols-15": { when: "od 1733", text: "Uliastaj vznikl jako pevnost dynastie Čching a z něj čínští úředníci spravovali Mongolsko. Leží v horách na západě země.", wiki: "Uliastaj" },
  "czechs-0": { when: "od 9. století", text: "Praha vyrostla pod Pražským hradem na Vltavě a za Karla IV. patřila k největším městům Evropy. Karel tu založil univerzitu a Nové Město a postavil kamenný most, kterému dnes říkáme Karlův.", wiki: "Praha" },
  "czechs-1": { when: "od 11. století", text: "Brno vyrostlo pod hradem Špilberkem a je největším městem Moravy. Roku 1645 se ubránilo švédskému obléhání a v klášteře tu Gregor Mendel objevil zákony dědičnosti.", wiki: "Brno" },
  "czechs-2": { when: "od 13. století", text: "Kutná Hora zbohatla na stříbře, které se tu těžilo ve středověku. Razily se tu pražské groše a stojí tu chrám svaté Barbory, postavený za peníze horníků.", wiki: "Kutná Hora" },
  "czechs-3": { when: "od 1295", text: "Plzeň založil král Václav II. na soutoku řek jako královské město. Roku 1842 tu uvařili první světlý ležák, podle kterého se pivo plzeň jmenuje na celém světě.", wiki: "Plzeň" },
  "czechs-4": { when: "od 11. století", text: "Olomouc byla dlouho hlavním městem Moravy a sídlem biskupů. Na náměstí stojí sloup Nejsvětější Trojice, který je památkou UNESCO, a orloj.", wiki: "Olomouc" },
  "czechs-5": { when: "od 13. století", text: "Hradec Králové býval věnným městem českých královen, odtud jméno. Roku 1866 u něj Prusové porazili rakouskou armádu.", wiki: "Hradec Králové" },
  "czechs-6": { when: "od 1265", text: "České Budějovice založil král Přemysl Otakar II. jako pevné královské město s velkým čtvercovým náměstím. Proslavilo je pivo a vedla odsud první koněspřežná železnice na kontinentu do Lince.", wiki: "České Budějovice" },
  "czechs-7": { when: "od 13. století", text: "Kolín leží na Labi a roku 1757 u něj rakouská armáda porazila pruského krále Fridricha Velikého. Na počest vítězství vznikl řád Marie Terezie.", wiki: "Kolín" },
  "czechs-8": { when: "od 1420", text: "Tábor založili husité na kopci nad řekou Lužnicí a pojmenovali ho po biblické hoře. Pod městem vykopali chodby, kde se skladovaly zásoby a ukrývali lidé.", wiki: "Tábor" },
  "czechs-9": { when: "od 12. století", text: "Cheb byl císařským městem s falcí Fridricha Barbarossy. Roku 1634 tu zavraždili vojevůdce Albrechta z Valdštejna.", wiki: "Cheb" },
  "czechs-10": { when: "od 1057", text: "Litoměřice leží na soutoku Labe a Ohře v úrodné krajině, které se říká zahrada Čech. Už v 11. století tu vzniklo kanovnictví a od 17. století tu sídlí biskup.", wiki: "Litoměřice" },
  "czechs-11": { when: "od 11. století", text: "Znojmo stojí na skále nad řekou Dyjí. V rotundě na hradě se zachovaly malby přemyslovských knížat a v okolí se pěstuje víno a okurky.", wiki: "Znojmo" },
  "czechs-12": { when: "od 13. století", text: "Jihlava vyrostla na stříbře a její horní právo převzala půlka Evropy. Pod náměstím vedou kilometry sklepů a chodeb a dětství tu prožil skladatel Gustav Mahler.", wiki: "Jihlava" },
  "czechs-13": { when: "od 13. století", text: "Opava byla hlavním městem Slezska v českých zemích. Roku 1820 se tu sešli panovníci Evropy na kongresu.", wiki: "Opava" },
  "czechs-14": { when: "od 13. století", text: "Písek vyrostl u brodu přes Otavu, kde se z písku ryžovalo zlato. Stojí tu nejstarší dochovaný kamenný most v Čechách.", wiki: "Písek" },
  "czechs-15": { when: "od 12. století", text: "Žatec obklopují chmelnice a jeho chmel se vozil do pivovarů po celém světě. Krajina chmelu je památkou UNESCO.", wiki: "Žatec" },
};

/**
 * The history of a city by its name, or null for a made-up name. The owner's
 * own list is searched first, so a Greek Thebes gets the Greek story.
 */
export function cityPage(name: string, ownerCiv: CivId): { page: CityPage; url: string } | null {
  const civs = [ownerCiv, ...CIV_IDS.filter((c) => c !== ownerCiv)];
  for (const civ of civs) {
    const index = CIVS[civ].cities.indexOf(name);
    if (index < 0) continue;
    const key = `${civ}-${index}`;
    const own = language().cities?.[key];
    const page = own ?? CITY_PAGES[key];
    if (!page) return null;
    const wikipedia = own ? (language().wikipedia ?? "cs") : "cs";
    // A search finds the article even when the title is written a little differently.
    return { page, url: `https://${wikipedia}.wikipedia.org/w/index.php?search=${encodeURIComponent(page.wiki)}` };
  }
  return null;
}
